        assertInteger("2^40", 1099511627776L, infix("^", num(2), num(40)));
        assertInteger("65536 DOT 65536", 4294967296L, infix("DOT", num(65536), num(65536)));
        assertInteger("65536 TIMES 65536", 4294967296L, infix("TIMES", num(65536), num(65536)));
