        assertInteger("-7 REM 2", -1, infix("REM", num(-7), num(2)));
        assertInteger("-7 MOD 2", 1, infix("MOD", num(-7), num(2)));
        assertInteger("7 MOD -2", -1, infix("MOD", num(7), num(-2)));
        assertInteger("12 GCD 18", 6, infix("GCD", num(12), num(18)));
