        // (2.5 + 2^-60) ulps of the least subnormal: one rounding gives 3 ulps
        BigInteger d64 = BigInteger.ONE.shiftLeft(1074 + 61);
        BigInteger n64 = BigInteger.valueOf(5).shiftLeft(60).add(BigInteger.ONE).shiftLeft(0);
        // n64/d64 = (5*2^60 + 1) / 2^(1135) = (2.5 + 2^-61) * 2^-1074
