        BigInteger d32 = BigInteger.ONE.shiftLeft(149 + 60);
        float gf = CodeGen.roundToFloat(n32, d32);
        float wf = new BigDecimal(n32).divide(new BigDecimal(d32)).floatValue();
        System.out.println("RR32 (2.5 + 2^-60) ulps: roundToFloat " + gf + " (" + (gf / Float.MIN_VALUE) + " ulps), BigDecimal " + wf + " (" + (wf / Float.MIN_VALUE) + " ulps)");
        // decimal numerals in the subnormal ranges
        String[] dec = { "0.0000000000000000000000000000000000000000000035032461608120430", "0.0000000000000000000000000000000000000000000042" };
        for (String s : dec) {
            BigDecimal b = new BigDecimal(s);
            BigInteger n = b.unscaledValue(), d = BigInteger.TEN.pow(b.scale());
            System.out.println("RR32 " + s + ": roundToFloat " + CodeGen.roundToFloat(n, d) + ", Float.parseFloat " + Float.parseFloat(s));
        }
        // random subnormal decimals: count mismatches
        Random r = new Random(29);
        int bad64 = 0, bad32 = 0, N = 200000;
        for (int i = 0; i < N; i++) {
            BigInteger n = new BigInteger(80, r);
            BigInteger d = BigInteger.TEN.pow(320 + r.nextInt(25)).multiply(BigInteger.valueOf(1000000));
            if (CodeGen.roundToDouble(n, d) != new BigDecimal(n).divide(new BigDecimal(d)).doubleValue()) bad64++;
            BigInteger d2 = BigInteger.TEN.pow(38 + r.nextInt(8)).multiply(BigInteger.valueOf(1000000));
