            // tuple type for the entire parameter list.
            boolean useClosure =
                !(fn instanceof FunctionalRef) 
                || ((FunctionalRef) fn).getStaticArgs().size() > 0
                || (fn instanceof FnRef && localFunctionOrNull((FnRef) fn) != null)
                ;

            if (useClosure) {
                if (fn instanceof FunctionalRef && ((FunctionalRef) fn).getStaticArgs().size() > 0 &&
                    assumptionCount(callArgList(arg)) > 0)
                    refuseGenericAssumption((FunctionalRef) fn);
                // Higher-order call.
                fn.accept(this); // Puts the VarRef function on the stack.
            }
            fnRefIsApply = false;
            Type domain_type = ((ArrowType)(x.getFunction().getInfo().getExprType().unwrap())).getDomain();
            evalArg(x, domain_type, arg);
            fnRefIsApply = true;
            if (useClosure) {
