            } else {
                callArgsForAssumption = callArgList(arg);
                try {
                    x.getFunction().accept(this);
                } finally {
                    callArgsForAssumption = null;
                }
            }
        } finally {
            paramCount = savedParamCount;
            fnRefIsApply = savedFnRefIsApply;
        }
