package com.sun.fortress.compiler.codegen;

import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.Random;

public class RoundAll {
    public static void main(String[] a) {
        Random r = new Random(2911);
        int N = 400000, bad64 = 0, bad32 = 0;
        for (int i = 0; i < N; i++) {
            BigInteger n = new BigInteger(1 + r.nextInt(120), r);
            if (n.signum() == 0) continue;
            int sc = r.nextInt(400) - 60;   // scale: negative scales make large values
            BigInteger d = sc >= 0 ? BigInteger.TEN.pow(sc) : BigInteger.ONE;
            BigInteger nn = sc >= 0 ? n : n.multiply(BigInteger.TEN.pow(-sc));
            BigDecimal exact = new BigDecimal(nn).divide(new BigDecimal(d));
            if (CodeGen.roundToDouble(nn, d) != exact.doubleValue()) bad64++;
            if (CodeGen.roundToFloat(nn, d) != exact.floatValue()) bad32++;
            // subnormal-range doubles and floats
            BigInteger d2 = BigInteger.TEN.pow(300 + r.nextInt(50));
            if (CodeGen.roundToDouble(n, d2) != new BigDecimal(n).divide(new BigDecimal(d2)).doubleValue()) bad64++;
            BigInteger d3 = BigInteger.TEN.pow(30 + r.nextInt(30));
            if (CodeGen.roundToFloat(n, d3) != new BigDecimal(n).divide(new BigDecimal(d3)).floatValue()) bad32++;
            // non-decimal denominators: compare with the exact rational by BigDecimal at 1200 digits then rounding is not exact, so test ties of powers of two
        }
        // exact ties and neighbours in powers of two: (k + 1/2) ulps of subnormals and normals
        int badTie = 0;
        for (int k = 0; k < 2000; k++) {
            for (int sh : new int[] { 1074 + 1, 149 + 1, 60, 0 }) {
                BigInteger num = BigInteger.valueOf(2L * k + 1);
                BigInteger den = BigInteger.ONE.shiftLeft(sh);
                BigDecimal ex = new BigDecimal(num).divide(new BigDecimal(den));
                if (CodeGen.roundToDouble(num, den) != ex.doubleValue()) badTie++;
                if (CodeGen.roundToFloat(num, den) != ex.floatValue()) badTie++;
            }
        }
        System.out.println("random decimals " + N + " x3: double mismatches " + bad64 + ", float mismatches " + bad32 + "; ties " + badTie);
    }
}
EOF
